import {CATALOG,defaultComposition,loadComposition,saveComposition,compositionErrors,signalChoices} from './station-config.js';
const labels={standard:'Origine',short:'Rampe courte',wide:'Rampe large',round:'Gyrophares ronds'};
export function openStationMenu(state,fleet){
 const dialog=document.createElement('dialog');dialog.className='stationComposer';document.body.append(dialog);const paused=state.paused;state.paused=true;state.composingStation=true;let rows=loadComposition(fleet)||defaultComposition(fleet),selected=0;const slots=fleet.filter(e=>e.kind!=='VLCG');
 const finish=()=>{state.paused=paused;state.composingStation=false;dialog.remove();};dialog.addEventListener('close',finish,{once:true});
 function draw(){const r=rows[selected],info=CATALOG[r.type],errors=compositionErrors(rows),active=rows.filter(r=>r.type).length;dialog.innerHTML=`<div class="composerHead"><div><small>CONFIGURATION DU CENTRE</small><h2>Composer ma caserne</h2></div><button data-close aria-label="Fermer">×</button></div><p class="composerHint">Pour la prochaine garde · ${active} engins + votre VLCG · 50 personnels</p><div class="composerBody"><div class="composerSlots">${[['Sanitaire · remise dédiée',true],['Incendie et appui',false]].map(([name,medical])=>`<section><h3>${name}</h3><div class="slotGrid">${rows.map((v,i)=>(slots[i].home[0]>-70)===medical?`<button data-slot="${i}" aria-pressed="${i===selected}"><small>Place ${i+1}</small><b>${v.type?CATALOG[v.type].label:'Libre'}</b></button>`:'').join('')}</div></section>`).join('')}<p class="composerHint">Chef de centre : VLCG conservée. Le choix voiture / camionnette reste dans votre profil.</p></div><section class="composerEditor"><div class="vehicleSketch" aria-hidden="true"><svg viewBox="0 0 260 115"><rect x="${info?.group==='medical'?60:35}" y="30" width="180" height="55" rx="5" fill="#d53235"/><path d="M35 85V55l25-25h35v55Z" fill="#d53235"/><path d="M43 53 63 34h23v22H43Z" fill="#243b43"/><path d="M100 36h130v40H100Z" fill="${info?.group==='medical'?'#d53235':'#a6b6b3'}"/><path d="M36 68h200" stroke="#eddb43" stroke-width="4"/><circle cx="65" cy="87" r="15" fill="#243035"/><circle cx="206" cy="87" r="15" fill="#243035"/>${r.signal==='round'?'<circle cx="76" cy="24" r="7" fill="#56b3ed"/><circle cx="219" cy="24" r="7" fill="#56b3ed"/>':`<rect x="${r.signal==='wide'?55:66}" y="20" width="${r.signal==='wide'?40:20}" height="8" rx="2" fill="#56b3ed"/>`}</svg></div><small class="composerHint">Schéma indicatif · aspect appliqué dans le jeu</small><label>Véhicule<select data-type><option value="">Place libre</option>${Object.entries(CATALOG).filter(([,v])=>v.group===(slots[selected].home[0]>-70?'medical':'fire')).map(([key,v])=>`<option value="${key}" ${r.type===key?'selected':''}>${v.label}</option>`).join('')}</select></label>${info?`<p class="composerHint">Équipage : ${info.crew} · ${info.group==='medical'?'Remise sanitaire':'Remise incendie / appui'}</p><label>Signalisation bleue<select data-signal>${signalChoices(r.type).map(key=>`<option value="${key}" ${r.signal===key?'selected':''}>${labels[key]}</option>`).join('')}</select></label>${['FPTSR','FPTL','CCF','CCF8000'].includes(r.type)?`<label class="equipmentOption"><input type="checkbox" data-foam ${r.foam?'checked':''}> Équipement mousse</label>`:''}${['FPTSR','EPA'].includes(r.type)?`<label class="equipmentOption"><input type="checkbox" data-lighting ${r.lighting?'checked':''}> ${r.type==='EPA'?'Éclairage nacelle':'Mât d’éclairage'}</label>`:''}<p class="composerHint">Signalisation orange et feux de pénétration conservés.</p>`:''}</section></div><p class="composerFeedback" role="status">${errors.join(' ')||'Composition compatible avec toutes les missions.'}</p><div class="composerActions"><button data-default>Composition initiale</button><button data-save ${errors.length?'disabled':''}>Enregistrer</button><button data-start ${errors.length?'disabled':''}>Nouvelle garde avec cette caserne</button></div><small class="composerFoot">Une nouvelle garde remplace la partie en cours. Enregistrer seul la conserve.</small>`;
 dialog.querySelector('[data-close]').onclick=()=>dialog.close();dialog.querySelectorAll('[data-slot]').forEach(b=>b.onclick=()=>{selected=Number(b.dataset.slot);draw();});dialog.querySelector('[data-type]').onchange=ev=>{r.type=ev.target.value;r.signal='standard';draw();};for(const prop of ['signal','foam','lighting']){const el=dialog.querySelector('[data-'+prop+']');if(el)el.onchange=()=>{r[prop]=prop==='signal'?el.value:el.checked;draw();};}dialog.querySelector('[data-default]').onclick=()=>{rows=defaultComposition(fleet);draw();};const save=()=>{const result=saveComposition(rows,fleet);dialog.querySelector('.composerFeedback').textContent=result.error||'Enregistré · appliqué à la prochaine nouvelle garde.';return !result.error;};dialog.querySelector('[data-save]').onclick=save;dialog.querySelector('[data-start]').onclick=()=>{if(!save())return;dialog.querySelector('.composerFeedback').textContent='La garde actuelle sera remplacée. Confirmer le démarrage ?';const b=dialog.querySelector('[data-start]');b.textContent='Confirmer la nouvelle garde';b.onclick=()=>{if(save())location.reload();};};
 }
 draw();dialog.showModal();return dialog;
}
